import React, { useState } from 'react';
import './css_files/analyzer.css'; // Ensure this file includes dark theme styles

const TwitterAnalyzer = () => {
  const [userInput, setUserInput] = useState('');
  const [sentiment, setSentiment] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  const handleInputChange = (e) => {
    setUserInput(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = `${e.target.scrollHeight}px`;
  };

  const analyzeSentiment = async () => {
    if (!userInput.trim()) return;

    setIsLoading(true);
    try {
      const response = await fetch('http://localhost:5000/predictTweet', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ text: userInput })
      });

      const data = await response.json();
      setSentiment(data);
    } catch (error) {
      console.error('Error fetching sentiment:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const getCompoundMarkerPosition = (score) => ((score + 1) / 2) * 100;

  return (
    <div className="analyzer-container">
      <div className="analyzer-card">
        <h2 className="analyzer-heading">Twitter Sentiment Analysis</h2>
        <p className="analyzer-subheading">Real-time analysis with ML-powered insights</p>

        <div className="input-section">
          <textarea
            className="tweet-input"
            value={userInput}
            onChange={handleInputChange}
            placeholder="Type your tweet here..."
          />
          <button
            className="analyze-btn"
            onClick={analyzeSentiment}
            disabled={isLoading}
          >
            {isLoading ? 'Analyzing...' : 'Analyze'}
          </button>
        </div>

        <div className="result-section">
          {isLoading && <p className="loading-text">Analyzing...</p>}
          {!isLoading && sentiment && (
            <div className="results">
              <div className={`sentiment-badge ${sentiment.sentiment.toLowerCase()}`}>
                {sentiment.sentiment}
              </div>
              <p className="confidence">Confidence: {(sentiment.confidence * 100).toFixed(2)}%</p>

              {['positive', 'neutral', 'negative'].map((key) => (
                <div className="score-row" key={key}>
                  <span className="score-label">{key.toUpperCase()}</span>
                  <div className="score-bar-bg">
                    <div
                      className={`score-bar ${key}`}
                      style={{ width: `${sentiment.vader_score[key] * 100}%` }}
                    />
                  </div>
                  <span className="score-value">{(sentiment.vader_score[key] * 100).toFixed(1)}%</span>
                </div>
              ))}

              <div className="compound-row">
                <span>Compound Score</span>
                <div className="compound-bar">
                  <div
                    className="compound-marker"
                    style={{ left: `${getCompoundMarkerPosition(sentiment.vader_score.compound)}%` }}
                  />
                </div>
                <span className="score-value">{sentiment.vader_score.compound.toFixed(3)}</span>
              </div>
            </div>
          )}
        </div>
        <p className="footer">Powered by RoBERTa and custom sentiment logic</p>
      </div>
    </div>
  );
};

export default TwitterAnalyzer;
